"""Add durable design sync without changing the apartment or scene renderer."""
from pathlib import Path
ROOT=Path(__file__).resolve().parent
def apply_cloud(s):
    def replace(old,new):
        nonlocal s
        assert old in s,old[:120]
        s=s.replace(old,new)
    replace('const STUDIO_CATALOG=',(ROOT/'studio-cloud-core.js').read_text()+'\nconst STUDIO_CATALOG=')
    replace('function save(){ try { localStorage.setItem(STORE, JSON.stringify(state)); } catch(e) {} }','function save(){ try { localStorage.setItem(STORE, JSON.stringify(state)); } catch(e) {} window.ApartmentCloud?.changed(); }')
    replace('<button class="btn primary" id="studioOptions">','<button class="btn" id="cloudDesign" title="Saved design, sync and previous versions"><span id="cloudIndicator" role="status" aria-live="polite">Saved design</span></button><button class="btn primary" id="studioOptions">')
    replace('<dialog id="studioDialog">','''<dialog id="cloudDialog"><div class="dialog-heading"><b>Saved design</b><button class="btn" id="cloudClose">Close</button></div><p id="cloudAccount"></p><p id="cloudStatus" role="status" aria-live="polite"></p><p id="cloudSavedAt" class="studio-note"></p><p id="cloudError" class="studio-callout"></p><div id="cloudConflict" hidden><p id="cloudConflictText"></p><div class="cloud-actions"><button class="btn primary" id="cloudUseSaved">Continue saved version</button><button class="btn" id="cloudUseDevice">Save this device version</button><button class="btn" id="cloudDownloadDraft">Download device draft</button></div></div><div class="cloud-actions"><button class="btn" id="cloudSyncNow">Sync now</button><button class="btn" id="cloudRecoverDraft">Recover last device draft</button><a class="btn" href="/signin-with-chatgpt?return_to=%2F" target="_top">Sign in</a></div><p class="studio-note">Completed edits save automatically for your ChatGPT account. Connected agents read the last saved scene and can apply validated furnishing proposals. Offline edits remain a device draft. Conflicting versions need your choice.</p><h3>Previous designs</h3><p class="studio-note">Recent saves are shown below. Up to 150 revisions are retained. Restore creates a new save.</p><div id="cloudHistory"></div></dialog>\n<dialog id="studioDialog">''')
    replace('Current browser edits travel through the exported brief; tools do not silently read this device or generate images inside the page.','Connected agents can read your latest saved design and apply validated proposals directly. The open viewer syncs their changes. Save pending drafts first. Image generation and screenshots are separate.')
    replace('Share a design brief with furniture, lighting or HVAC agents. Import their proposal to validate its scene version, IDs and allowed changes before applying it. Geometry and ceiling-height changes are rejected.','Connected agents read the saved design, validate proposals and apply them directly. You can also export a brief or import a proposal. Scene revisions protect concurrent edits; geometry and ceiling-height changes are rejected.')
    replace('Changes save on this device. Use File to export your layout.','Completed edits save to your account. Saved design shows sync status and previous versions. File exports a copy.')
    replace('Colour and floor edits stay saved for each style on this device.','Colour and floor edits stay saved for each style in your design.')
    replace('/* Type B studio */', '''#cloudDialog{width:min(620px,calc(100vw - 28px));max-height:85vh;overflow:auto;border-radius:16px;padding:20px;background:#fff;color:#263750;border:1px solid #dce5ef}#cloudDialog::backdrop{background:#14253b80}#cloudDialog .dialog-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}#cloudStatus{font-weight:650}#cloudError:empty{display:none}.cloud-actions{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.cloud-history-row{display:flex;align-items:center;justify-content:space-between;gap:14px;border-top:1px solid #e3e9ee;padding:12px 0}.cloud-history-row span{white-space:pre-line;font-size:13px;line-height:1.5}#cloudIndicator[data-state="conflict"]{color:#9a531b}#cloudIndicator[data-state="draft"]{color:#4a6386}#cloudConflict{background:#fff8ed;padding:12px;border-radius:10px}#cloudConflict[hidden]{display:none}#cloudDesign{font-size:11px;max-width:180px;overflow:hidden;text-overflow:ellipsis}\n/* Type B studio */''')
    # Run after the viewer has initialized its DOM and state.
    replace('<a class="btn" href="/signin-with-chatgpt?return_to=%2F"','<a class="btn" id="cloudSignIn" href="/signin-with-chatgpt?return_to=%2F"')
    marker='</script>\n<script type="module">'
    replace(marker,(ROOT/'studio-cloud.js').read_text()+'\n'+marker)
    return s
